package com.lyrashop.user.controller;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import com.lyrashop.user.entity.PaymentMethodToken;import com.lyrashop.user.repository.PaymentMethodRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api/v1/me/payment-methods") public class PaymentMethodController{private final PaymentMethodRepository r;public PaymentMethodController(PaymentMethodRepository r){this.r=r;}public record Req(@NotBlank @Size(max=50)String provider,@NotBlank @Size(max=255)String providerToken,@NotBlank @Size(max=100)String displayName,@Pattern(regexp="\\d{4}")String lastFour){}private UUID uid(Authentication a){return UUID.fromString(a.getName());}private Map<String,Object> out(PaymentMethodToken p){var m=new LinkedHashMap<String,Object>();m.put("id",p.getId());m.put("provider",p.getProvider());m.put("displayName",p.getDisplayName());m.put("lastFour",p.getLastFour());m.put("isDefault",p.isDefaultMethod());return m;}
 @GetMapping public List<Map<String,Object>> list(Authentication a){return r.findAllByUserId(uid(a)).stream().map(this::out).toList();}
 @PostMapping @Transactional public ResponseEntity<Map<String,Object>> add(Authentication a,@Valid @RequestBody Req q){var p=new PaymentMethodToken(uid(a),q.provider(),q.providerToken(),q.displayName(),q.lastFour());if(r.findAllByUserId(uid(a)).isEmpty())p.setDefault(true);return ResponseEntity.status(201).body(out(r.save(p)));}
 @PatchMapping("/{id}/default")@Transactional public Map<String,Object> def(Authentication a,@PathVariable UUID id){var all=r.findAllByUserId(uid(a));all.forEach(p->p.setDefault(p.getId().equals(id)));r.saveAll(all);return out(r.findByIdAndUserId(id,uid(a)).orElseThrow());}
 @DeleteMapping("/{id}")@Transactional public ResponseEntity<Void> del(Authentication a,@PathVariable UUID id){r.findByIdAndUserId(id,uid(a)).ifPresent(r::delete);return ResponseEntity.noContent().build();}}
